/**
 * 100-day-plan.js — Renders site/100-day-plan.json as a time x focus-area
 * grid. Same "content as data" pattern as build.js/dora-metrics.js: plain
 * JS, no build step. Unlike the DORA/security scorecards, this data file
 * is static and hand-authored (not generated by a scheduled workflow), so
 * it's a normal git-tracked file, not gitignored.
 */

(function () {
  'use strict';

  function esc(str) {
    if (str === null || str === undefined) return '';
    return String(str)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#39;');
  }

  function renderFraming(data) {
    const el = document.getElementById('plan-framing');
    if (el) el.textContent = data.framing;
  }

  function renderGrid(data) {
    const container = document.getElementById('plan-grid');
    if (!container) return;

    const periods = data.time_periods;

    const headerCells = periods.map((p) => `<th scope="col">${esc(p.label)}</th>`).join('');

    const rows = data.focus_areas
      .map((fa) => {
        const cells = periods
          .map((p) => {
            const items = (data.plan[fa.key] && data.plan[fa.key][p.key]) || [];
            const list = items.map((item) => `<li>${esc(item)}</li>`).join('');
            return `<td><ul>${list}</ul></td>`;
          })
          .join('');
        return `
        <tr id="focus-${esc(fa.key)}">
          <th scope="row">
            <div class="plan-row-label">${esc(fa.label)}</div>
            <div class="plan-row-desc">${esc(fa.description)}</div>
          </th>
          ${cells}
        </tr>
      `;
      })
      .join('');

    container.innerHTML = `
      <div class="plan-table-wrapper">
        <table class="plan-table">
          <thead>
            <tr><th scope="col">Focus area</th>${headerCells}</tr>
          </thead>
          <tbody>${rows}</tbody>
        </table>
      </div>
    `;
  }

  function renderPrintSections(data) {
    const container = document.getElementById('plan-grid-print');
    if (!container) return;

    const periods = data.time_periods;

    container.innerHTML = data.focus_areas
      .map((fa) => {
        const cols = periods
          .map((p) => {
            const items = (data.plan[fa.key] && data.plan[fa.key][p.key]) || [];
            const list = items.map((item) => `<li>${esc(item)}</li>`).join('');
            return `
            <div class="print-plan-col">
              <div class="print-plan-col-label">${esc(p.label)}</div>
              <ul>${list}</ul>
            </div>
          `;
          })
          .join('');
        return `
        <section class="print-plan-section">
          <h3>${esc(fa.label)} <span class="print-plan-desc">— ${esc(fa.description)}</span></h3>
          <div class="print-plan-columns">${cols}</div>
        </section>
      `;
      })
      .join('');
  }

  function renderPrintMarketing(resume) {
    const container = document.getElementById('print-marketing');
    if (!container || !resume) return;

    const highlights = (resume.highlights || []).slice(0, 4);
    const cards = highlights
      .map(
        (h) => `
        <div class="print-highlight">
          <div class="print-highlight-title">${esc(h.title)}</div>
          <div class="print-highlight-desc">${esc(h.description)}</div>
        </div>
      `
      )
      .join('');

    container.innerHTML = `
      <p class="print-marketing-summary">${esc(resume.summary || '')}</p>
      <div class="print-highlights">${cards}</div>
    `;
  }

  function render([plan, resume]) {
    renderFraming(plan);
    renderGrid(plan);
    renderPrintSections(plan);
    renderPrintMarketing(resume);
  }

  Promise.all([
    fetch('100-day-plan.json').then(function (res) {
      if (!res.ok) throw new Error('Failed to load 100-day plan: ' + res.status);
      return res.json();
    }),
    fetch('content.json')
      .then(function (res) {
        return res.ok ? res.json() : null;
      })
      .catch(function () {
        return null;
      }),
  ])
    .then(render)
    .catch(function (err) {
      console.error('100-day plan could not be loaded.', err);
      const framing = document.getElementById('plan-framing');
      if (framing) framing.textContent = 'Plan data is not available yet.';
      const grid = document.getElementById('plan-grid');
      if (grid) grid.textContent = 'Plan data is not available yet.';
    });
}());
